//! 1c read parity: the sfnt model against `Fontisan::Reference.read` for every
//! ci-tier ttf/otf/ttc face in all four mode/lazy combinations.
//!
//! TODO(0b): expected values come from `read/expected.json`, generated by
//! `scripts/read-expected.rb` against the Ruby facade, because card 0b has not
//! published `corpus/goldens/read/*.json` yet. When it does, read those
//! (the schema is the same facade output) and delete the script and fixture.
mod common;

use common::*;
use fontisan::sfnt::{Font, LoadingMode, Options, face_count};
use serde_json::Value;

#[test]
fn every_ci_font_face_matches_ruby_in_all_modes() {
    let Some(corpus) = corpus() else { return };
    let exp: Value = serde_json::from_str(include_str!("read/expected.json")).unwrap();
    let fonts = exp["fonts"].as_object().unwrap();
    assert!(
        fonts.len() >= 25,
        "expected fixture too small: {}",
        fonts.len()
    );
    let mut checked = 0;
    for (name, want) in fonts {
        let bytes = std::fs::read(font_path(&corpus, name)).unwrap();
        let faces = want["faces"].as_array().unwrap();
        assert_eq!(face_count(&bytes), Some(faces.len()), "{name}: face count");
        for (i, face) in faces.iter().enumerate() {
            for (combo, opts) in combos() {
                let font =
                    load(&bytes, i, opts).unwrap_or_else(|e| panic!("{name}[{i}] {combo}: {e}"));
                let (got, extra) =
                    read_face(&bytes, &font).unwrap_or_else(|e| panic!("{name}[{i}] {combo}: {e}"));
                assert_eq!(got, face["combos"][combo], "{name}[{i}] {combo}");
                assert_eq!(extra["names"], face["names"], "{name}[{i}] {combo}: names");
                assert_eq!(
                    extra["post_glyph_names"], face["post_glyph_names"],
                    "{name}[{i}] {combo}: post"
                );
                checked += 1;
            }
        }
    }
    eprintln!("read parity: {checked} face/mode combinations match Ruby");
}

#[test]
fn metadata_mode_gates_other_tables_and_full_mode_does_not() {
    let Some(corpus) = corpus() else { return };
    let bytes = std::fs::read(font_path(&corpus, "TestTTF.ttf")).unwrap();
    let meta = Font::load(
        &bytes,
        0,
        Options {
            mode: LoadingMode::Metadata,
            lazy: true,
        },
    )
    .unwrap();
    let err = meta.cmap().unwrap_err();
    assert_eq!(err.class.ruby_name(), "ArgumentError");
    assert_eq!(
        err.message,
        r#"Table 'cmap' is not available in metadata mode. Available tables: ["name", "head", "hhea", "maxp", "OS/2", "post"]"#
    );
    assert!(meta.table_data("cmap").is_none() && meta.table_data("head").is_some());
    assert!(Font::from_bytes(&bytes).unwrap().cmap().unwrap().is_some());
}

#[test]
fn collection_index_out_of_range_matches_ruby_message() {
    let Some(corpus) = corpus() else { return };
    let bytes = std::fs::read(font_path(&corpus, "TestTTC.ttc")).unwrap();
    let e = Font::load(&bytes, 7, Options::default()).err().unwrap();
    assert_eq!(e.class.ruby_name(), "Fontisan::InvalidFontError");
    assert_eq!(
        e.message,
        "Font index 7 out of range (collection has 2 fonts)"
    );
}

/// Ruby's PFA signatures are `%!PS-AdobeFont-1.0` / `%!PS-Adobe-3.0 Resource-Font`;
/// the corpus pfa starts `%!FontType1-1.1`, which Ruby itself does not recognise.
#[test]
fn corpus_pfa_is_unrecognised_exactly_like_ruby() {
    let Some(corpus) = corpus() else { return };
    let bytes = std::fs::read(font_path(&corpus, "TestT1-Regular.pfa")).unwrap();
    let e = Font::from_bytes(&bytes).err().unwrap();
    assert_eq!(e.class.ruby_name(), "Fontisan::InvalidFontError");
}

#[test]
fn dfont_and_type1_are_unsupported_not_misparsed() {
    let Some(corpus) = corpus() else { return };
    for name in ["TestT1-Regular.pfb", "TestDFONT.dfont"] {
        let bytes = std::fs::read(font_path(&corpus, name)).unwrap();
        let e = Font::from_bytes(&bytes)
            .err()
            .unwrap_or_else(|| panic!("{name} loaded"));
        assert_eq!(e.class, fontisan::sfnt::ErrorClass::Unsupported, "{name}");
    }
}
